package cn.nemo.qingxiao;
import android.app.*;import android.content.*;import android.net.Uri;import android.os.Build;import org.json.*;import java.util.*;
public class Reminders {
 static String key(String id,String sid){return id+"/"+sid;}
 static PendingIntent pending(Context c,String id,String sid,long at){return PendingIntent.getBroadcast(c,0,new Intent(c,ReminderReceiver.class).addFlags(Intent.FLAG_RECEIVER_FOREGROUND).setData(Uri.parse("qingxiao://reminder/"+Uri.encode(key(id,sid)))).putExtra("id",id).putExtra("subtaskId",sid).putExtra("remindAt",at),PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);}
 static void schedule(Context c,AlarmManager m,Set<String> ids,String id,String sid,JSONObject target)throws Exception{long at=target.optLong("remindAt");if(at<=System.currentTimeMillis()||target.optBoolean("done"))return;PendingIntent pi=pending(c,id,sid,at);try{if(Build.VERSION.SDK_INT<31||m.canScheduleExactAlarms())m.setExactAndAllowWhileIdle(AlarmManager.RTC_WAKEUP,at,pi);else m.setAndAllowWhileIdle(AlarmManager.RTC_WAKEUP,at,pi);ids.add(key(id,sid));}catch(SecurityException e){m.setAndAllowWhileIdle(AlarmManager.RTC_WAKEUP,at,pi);ids.add(key(id,sid));}}
 public static void sync(Context c){synchronized(Store.class){try{AlarmManager m=c.getSystemService(AlarmManager.class);SharedPreferences pref=c.getSharedPreferences("alarms",0);for(String old:pref.getStringSet("ids",new HashSet<>())){int slash=old.indexOf('/');if(slash<0){Intent legacy=new Intent(c,ReminderReceiver.class).addFlags(Intent.FLAG_RECEIVER_FOREGROUND).setData(Uri.parse("qingxiao://reminder/"+Uri.encode(old))).putExtra("id",old);m.cancel(PendingIntent.getBroadcast(c,0,legacy,PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE));}else m.cancel(pending(c,old.substring(0,slash),old.substring(slash+1),0));}Set<String> ids=new HashSet<>();JSONArray items=new JSONObject(Store.read(c)).getJSONArray("items");for(int i=0;i<items.length();i++){JSONObject t=items.getJSONObject(i);if(t.optBoolean("done")||t.optBoolean("deleted"))continue;String id=t.getString("id");schedule(c,m,ids,id,"",t);JSONArray subs=t.optJSONArray("subtasks");if(subs!=null)for(int j=0;j<subs.length();j++){JSONObject sub=subs.getJSONObject(j);if(!sub.optString("id").isEmpty())schedule(c,m,ids,id,sub.getString("id"),sub);}}pref.edit().putStringSet("ids",ids).apply();DayReminder.schedule(c);}catch(Exception e){android.util.Log.e("Qingxiao","Reminder scheduling failed",e);}}}
}
